/// 按名字查 POI 类型 ID，存档的 `type` 键用它。
pub fn poi_type_id(name: &str) -> Option<u8> {
    let name = name.strip_prefix("minecraft:").unwrap_or(name);
    POI_TYPES.iter().position(|poi| poi.name == name).map(|id| id as u8)
}

/// `PoiTypes.forState`：状态 ID → POI 类型 ID。
pub fn for_state(state: u32) -> Option<u8> {
    STATE_POI_TYPE.get(usize::try_from(state).ok()?).copied().flatten()
}
